# typed: false
# frozen_string_literal: true

# Homebrew formula for the Engra CLI. Generated by packaging/release.py in the
# release workflow; do not hand-edit. Release assets live in
# arenberg-engineering/engra-releases.
class Engra < Formula
  desc "AI coding agent and developer assistant for the terminal"
  homepage "https://engra.io"
  # Proprietary software of Arenberg AG, all rights reserved (LICENSE.txt).
  license :cannot_represent

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/arenberg-engineering/engra-releases/releases/download/v0.3.0/engra-0.3.0-macos-arm64.tar.gz"
      sha256 "92b7e85ce6df6464eb8725f4b079880b323d278731a1504a61b1d80c73716920"
    end
    on_intel do
      url "https://github.com/arenberg-engineering/engra-releases/releases/download/v0.3.0/engra-0.3.0-macos-x64.tar.gz"
      sha256 "9c28746a6fe74afe4998f26b72dfc4ce9d104d5f866e025009c744c03d0e803a"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/arenberg-engineering/engra-releases/releases/download/v0.3.0/engra-0.3.0-linux-arm64.tar.gz"
      sha256 "517148c66ab09edf952817c5a759607e361168e6349f95acb2b343263342fddd"
    end
    on_intel do
      url "https://github.com/arenberg-engineering/engra-releases/releases/download/v0.3.0/engra-0.3.0-linux-x64.tar.gz"
      sha256 "5ea4200483c24c9184be666ea0d8bdf0d4e30aacfcb943515d742437e5b7bc89"
    end
  end

  def install
    libexec.install "engra", "_internal"
    bin.install_symlink libexec/"engra"
    prefix.install "LICENSE.txt", "TERMS.md", "THIRD_PARTY_NOTICES.txt"
  end

  def caveats
    <<~EOS
      Sign in with:
        engra login

      Terms of Use: engra legal --terms

      Before uninstalling, run `engra logout` to remove saved credentials from
      the OS keychain. Settings and link state stay in ~/.config/engra (and
      doctor records in ~/.engra); remove them to clear everything.
    EOS
  end

  test do
    assert_equal "engra #{version}", shell_output("#{bin}/engra --version").strip
    assert_match "doctor", shell_output("#{bin}/engra --help")
    assert_match "Arenberg AG", shell_output("#{bin}/engra legal")
  end
end
